import { writable, derived } from "svelte/store";

const { subscribe, set, update } = writable([]);

export const taskStore = {
  subscribe,
  add: (task) => update(tasks => [...tasks, { ...task, id: Date.now(), done: false }]),
  toggle: (id) => update(tasks => tasks.map(t => t.id === id ? { ...t, done: !t.done } : t)),
  remove: (id) => update(tasks => tasks.filter(t => t.id !== id)),
  clearDone: () => set(tasks.filter(t => !t.done)),
};

export const activeTasks = derived(taskStore, $tasks => $tasks.filter(t => !t.done));
export const doneTasks = derived(taskStore, $tasks => $tasks.filter(t => t.done));
export const taskCount = derived(taskStore, $tasks => $tasks.length);
